use kurvst::marks::{MarkContext, MarkSpec, MarkSize, MarkStrokeStyle};
use std::env;
fn main() {
    let args: Vec<_> = env::args().collect();
    let shape = args.get(1).expect("shape").clone();
    let parse = |i| args.get(i).and_then(|x: &String| x.parse::<f64>().ok());
    let size = |i| parse(i).map(|points| MarkSize { points, ratio: 0.0 });
    let spec = MarkSpec { shape, fit: None, shorten: None, length: size(2), width: size(3),
        inset: parse(5), arc: parse(6), phase: None, n: None, rev: None, align: None,
        fill: Some(false), stroke: Some(true), parts: None };
    let mut spec = spec;
    if !matches!(spec.shape.as_str(), "triangle"|"stealth"|"round"|"circle"|"square"|"diamond") { spec.fill = None; }
    if args.get(7).is_some_and(|x| x == "rev") {spec.rev = Some(true);}
    let ctx = MarkContext {units_per_pt: 1.0, line_thickness: parse(4).unwrap_or(1.0), shaft_stroke: MarkStrokeStyle::default()};
    match spec.prepare(ctx) {
        Err(e) => println!("ERROR {e}"),
        Ok(p) => {
            println!("end={:?}",p.end());
            for path in p.paths() {
                println!("miter={:?} path_finite={} outline_finite={}",path.miter_limit,path.path.path.is_finite(),path.outline.path.is_finite());
                println!("path={:?}",path.path.path.elements());
                println!("outline_bounds={:?}",path.outline_bounds);
            }
        }
    }
}

